  // js/dal/DataSource.js
  var DataAccessError = class extends Error {
    constructor(message, { cause, path } = {}) {
      super(message, { cause });
      this.name = "DataAccessError";
      this.path = path;
    }
  };
  var DataSource = class _DataSource {
    constructor() {
      if (new.target === _DataSource) {
        throw new TypeError("DataSource \xE9 abstrata: use uma subclasse.");
      }
    }
    /** @param {string} path @returns {Promise<unknown>} */
    async read(path) {
      throw new Error(`${this.constructor.name}.read(${path}) n\xE3o implementado.`);
    }
  };
  var StaticDataSource = class extends DataSource {
    #records;
    /** @param {Record<string, unknown>} records Mapa caminho → dados */
    constructor(records) {
      super();
      this.#records = new Map(Object.entries(records));
    }
    async read(path) {
      if (!this.#records.has(path)) {
        throw new DataAccessError(`Dado n\xE3o encontrado: ${path}`, { path });
      }
      return this.#records.get(path);
    }
  };

  // js/dal/Repository.js
  var Repository = class _Repository {
    #source;
    /** @param {DataSource} source */
    constructor(source) {
      if (new.target === _Repository) {
        throw new TypeError("Repository \xE9 abstrata: use uma subclasse.");
      }
      if (!(source instanceof DataSource)) {
        throw new TypeError(`${new.target.name}: informe uma DataSource.`);
      }
      this.#source = source;
    }
    /** @protected */
    read(path) {
      return this.#source.read(path);
    }
  };

